package com.jotafy.app;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.util.concurrent.*;
public class MonitorService extends Service {
 ScheduledExecutorService timer;NotificationManager manager;boolean running;
 Notification notice(String title,String body,String channel){PendingIntent p=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);return new Notification.Builder(this,channel).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(title).setContentText(body).setContentIntent(p).setAutoCancel(!channel.equals("monitor")).setOngoing(channel.equals("monitor")).build();}
 @Override public int onStartCommand(Intent i,int flags,int id){if(running)return START_NOT_STICKY;running=true;manager=getSystemService(NotificationManager.class);manager.createNotificationChannel(new NotificationChannel("monitor","Status do monitoramento",NotificationManager.IMPORTANCE_LOW));manager.createNotificationChannel(new NotificationChannel("sales","Vendas e pagamentos",NotificationManager.IMPORTANCE_DEFAULT));startForeground(1,notice("JotaFy ativo","Consultando vendas a cada minuto","monitor"));timer=Executors.newSingleThreadScheduledExecutor();timer.scheduleWithFixedDelay(()->poll(),0,60,TimeUnit.SECONDS);return START_NOT_STICKY;}
 void poll(){try{JSONObject j=Store.load(this,1,true);JSONArray events=j.getJSONArray("events");for(int n=0;n<events.length();n++){JSONObject e=events.getJSONObject(n);try{manager.notify((int)(e.getLong("seq")%2147483645L)+2,notice(Store.label(e.getString("kind")),Store.money(e.getLong("amount_cents"))+" • "+Store.label(e.getString("method")),"sales"));}catch(SecurityException ignored){}}Store.prefs(this).edit().putLong("cursor",j.getLong("cursor")).commit();manager.notify(1,notice("JotaFy ativo","Última consulta concluída • a cada minuto","monitor"));}catch(Exception e){manager.notify(1,notice("JotaFy sem conexão","Abra o app para verificar conexão e chave","monitor"));}}
 @Override public void onTimeout(int startId,int type){stopSelf();}
 @Override public void onDestroy(){if(timer!=null)timer.shutdownNow();running=false;stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
